create or replace function public.submit_location_quality_observation(p_location_id uuid,p_stars smallint,p_cleanliness numeric default null,p_accessibility numeric default null,p_safety numeric default null,p_availability numeric default null,p_condition numeric default null,p_feedback text default null,p_check_in_id uuid default null,p_photo_id uuid default null,p_metadata jsonb default '{}'::jsonb) returns public.location_quality_observations language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); r public.location_quality_observations; begin if uid is null then raise exception 'Authentication required'; end if; if p_stars is not null and (p_stars<1 or p_stars>5) then raise exception 'Rating must be 1 to 5'; end if; insert into public.location_quality_observations(location_id,user_id,check_in_id,cleanliness_score,accessibility_score,safety_score,availability_score,condition_score,overall_stars,feedback,photo_id,observed_at,metadata) values(p_location_id,uid,p_check_in_id,p_cleanliness,p_accessibility,p_safety,p_availability,p_condition,p_stars,p_feedback,p_photo_id,now(),coalesce(p_metadata,'{}'::jsonb)) returning * into r; perform public.record_progression_metric_event('review','location_quality_observation',r.id,1,20,jsonb_build_object('location_id',p_location_id,'stars',p_stars)); return r; end $$; revoke all on function public.submit_location_quality_observation(uuid,smallint,numeric,numeric,numeric,numeric,numeric,text,uuid,uuid,jsonb) from public; grant execute on function public.submit_location_quality_observation(uuid,smallint,numeric,numeric,numeric,numeric,numeric,text,uuid,uuid,jsonb) to authenticated;
create or replace function public.submit_amenity_observation(p_location_id uuid,p_amenity_id uuid,p_status text,p_confidence numeric default null,p_verification_method text default 'user',p_check_in_id uuid default null,p_photo_id uuid default null,p_notes text default null,p_metadata jsonb default '{}'::jsonb) returns public.location_amenity_observations language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); r public.location_amenity_observations; begin if uid is null then raise exception 'Authentication required'; end if; if lower(coalesce(p_status,'')) not in ('present','absent','unknown') then raise exception 'Amenity status must be present, absent, or unknown'; end if; insert into public.location_amenity_observations(location_id,user_id,amenity_id,status,confidence,verification_method,check_in_id,photo_id,notes,observed_at,metadata) values(p_location_id,uid,p_amenity_id,lower(p_status),p_confidence,p_verification_method,p_check_in_id,p_photo_id,p_notes,now(),coalesce(p_metadata,'{}'::jsonb)) returning * into r; perform public.record_progression_metric_event('verification','amenity_observation',r.id,1,15,jsonb_build_object('location_id',p_location_id,'amenity_id',p_amenity_id,'status',lower(p_status))); return r; end $$; revoke all on function public.submit_amenity_observation(uuid,uuid,text,numeric,text,uuid,uuid,text,jsonb) from public; grant execute on function public.submit_amenity_observation(uuid,uuid,text,numeric,text,uuid,uuid,text,jsonb) to authenticated;
create or replace function public.submit_location_photo_record(p_location_id uuid,p_storage_path text,p_caption text default null,p_media_type text default 'image',p_mime_type text default null,p_size_bytes bigint default null,p_width integer default null,p_height integer default null) returns public.location_photos language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); r public.location_photos; begin if uid is null then raise exception 'Authentication required'; end if; insert into public.location_photos(location_id,user_id,storage_path,caption,media_type,mime_type,size_bytes,width,height,created_at) values(p_location_id,uid,p_storage_path,p_caption,p_media_type,p_mime_type,p_size_bytes,p_width,p_height,now()) returning * into r; perform public.record_progression_metric_event('verification','location_photo',r.id,1,10,jsonb_build_object('location_id',p_location_id)); return r; end $$; revoke all on function public.submit_location_photo_record(uuid,text,text,text,text,bigint,integer,integer) from public; grant execute on function public.submit_location_photo_record(uuid,text,text,text,text,bigint,integer,integer) to authenticated;
